function d(r,t=0){const n=String(r).trim();if(!/^-?\d+(\.\d+)?$/.test(n))throw new Error("Invalid token amount");const o=n.startsWith("-"),s=o?n.slice(1):n,[a,e=""]=s.split(".");if(e.length>t)throw new Error(`Amount has more precision than token decimals (${t})`);const c=e.padEnd(t,"0"),i=BigInt(a||"0")*10n**BigInt(t)+BigInt(c||"0");return o?-i:i}function h(r,t){return r*10**t}export{d,h as p};
